  "plasma.pyre": "# Plasma: layered sine waves run through a cosine palette.\nuniform time: float\n\n@fragment\nfn main(uv: vec2) -> vec4:\n    let p = (uv - 0.5) * 6.0\n    var v = sin(p.x + time)\n    v += sin((p.y + time) * 0.5)\n    v += sin((p.x + p.y + time) * 0.5)\n    let c = p + vec2(sin(time / 3.0), cos(time / 2.0)) * 2.0\n    v += sin(sqrt(dot(c, c) + 1.0) + time)\n    let col = palette(v * 0.25, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.0, 0.33, 0.67))\n    return vec4(col, 1.0)\n",
  "raymarch.pyre": "# Signed-distance raymarcher: a blobby torus and sphere with soft lighting.\nuniform time: float\n\nfn scene(p: vec3) -> float:\n    let q = vec3(rotate(time * 0.7) * p.xz, p.y).xzy\n    let torus = sdTorus(q, vec2(0.9, 0.28))\n    let ball = sdSphere(p - vec3(sin(time) * 1.2, 0.0, 0.0), 0.45)\n    return smin(torus, ball, 0.35)\n\nfn normal_at(p: vec3) -> vec3:\n    let e = 0.001\n    return normalize(vec3(\n        scene(p + vec3(e, 0.0, 0.0)) - scene(p - vec3(e, 0.0, 0.0)),\n        scene(p + vec3(0.0, e, 0.0)) - scene(p - vec3(0.0, e, 0.0)),\n        scene(p + vec3(0.0, 0.0, e)) - scene(p - vec3(0.0, 0.0, e))))\n\n@fragment\nfn main(uv: vec2) -> vec4:\n    let ro = vec3(0.0, 0.6, 3.2)\n    let rd = normalize(vec3((uv - 0.5) * 2.0, -1.6) - vec3(0.0, 0.18, 0.0))\n    var t = 0.0\n    var hit = false\n    for i in range(96):\n        let d = scene(ro + rd * t)\n        if d < 0.001:\n            hit = true\n            break\n        t += d\n        if t > 8.0:\n            break\n    var col = mix(vec3(0.02, 0.02, 0.05), vec3(0.10, 0.05, 0.20), uv.y)\n    if hit:\n        let p = ro + rd * t\n        let n = normal_at(p)\n        let light = normalize(vec3(0.6, 0.8, 0.4))\n        let diff = max(dot(n, light), 0.0)\n        let rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0)\n        let base = palette(p.y * 0.4 + time * 0.1, vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.95, 0.35, 0.05))\n        col = base * (0.15 + diff) + rim * vec3(1.0, 0.45, 0.1)\n    return vec4(pow(col, vec3(0.4545)), 1.0)\n",
  "features.pyre": "# A tour of the language: every feature here is checked on real GPUs by\n# scripts/gpu-check.mjs and must render identically on the CPU.\nuniform time: float\nconst STEPS = 4\nconst TINT: vec3 = vec3(0.9, 0.7, 1.0)\n\nfn checker(p: vec2, cells: int) -> float:\n    let c = floor(p * float(cells))\n    let parity = (int(c.x) + int(c.y)) & 1          # bitwise and on ints\n    return 1.0 if parity == 0 else 0.6               # conditional expression\n\nfn texture(input: vec2) -> vec3:                     # reserved words are renamed\n    var col = hsv2rgb(vec3(hash21(floor(input * 8.0)), 0.6, 1.0))\n    col.g *= 0.8                                     # swizzle assignment\n    return col\n\n@fragment\nfn main(uv: vec2, frag: vec2) -> vec4:\n    let m = rotate(time * 0.25) * mat2(1.2)          # matrix maths\n    let p = m * (uv - 0.5)\n    var col = texture(p + 0.5) * checker(uv, 6)\n    var glow = 0.0\n    for i in range(STEPS):\n        let r = 0.1 + 0.08 * float(i)\n        glow += 0.004 / abs(length(p) - r)\n    var k = 0\n    while k < 3:\n        k += 1\n        if k == 2:\n            continue\n        elif k > 2:\n            break\n        col = mix(col, TINT, 0.15)\n    let box = sdBox(vec3(p, 0.0), vec3(0.15))\n    col += vec3(1.0, 0.5, 0.2) * smoothstep(0.01, 0.0, abs(box))\n    col += glow * vec3(0.4, 0.6, 1.0)\n    let stripes = float(int(frag.x) % 4 == 0) * 0.05   # frag = pixel coords\n    return vec4(clamp(col - stripes, 0.0, 1.0), 1.0)\n",
  "lava.pyre": "# Lava material for 3D models: uses the mesh normal and position.\nuniform time: float\n\n@fragment\nfn main(normal: vec3, position: vec3, uv: vec2) -> vec4:\n    let flow = fbm(position.xy * 2.5 + vec2(0.0, -time * 0.4))\n    let heat = smoothstep(0.35, 0.75, flow)\n    let crust = vec3(0.08, 0.02, 0.02)\n    let lava = mix(vec3(1.0, 0.25, 0.0), vec3(1.0, 0.85, 0.3), heat)\n    let light = max(dot(normal, normalize(vec3(0.4, 0.8, 0.6))), 0.0)\n    let rim = pow(1.0 - abs(normal.z), 2.5)\n    let col = mix(crust * (0.3 + light), lava, heat) + rim * vec3(1.0, 0.4, 0.1) * 0.6\n    return vec4(col, 1.0)\n",
  "mandelbrot.pyre": "# Mandelbrot set with smooth colouring and a slow zoom.\nuniform time: float\nconst MAX_ITER = 200\n\n@fragment\nfn main(uv: vec2) -> vec4:\n    let zoom = 1.5 / (1.0 + 0.15 * time)\n    let c = (uv - 0.5) * 2.0 * zoom + vec2(-0.7436, 0.1318)\n    var z = vec2(0.0)\n    var n = 0\n    while n < MAX_ITER and dot(z, z) < 256.0:\n        z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c\n        n += 1\n    if n == MAX_ITER:\n        return vec4(0.0, 0.0, 0.0, 1.0)\n    let smooth_n = float(n) - log2(log2(dot(z, z))) + 4.0\n    let col = 0.5 + 0.5 * cos(3.0 + smooth_n * 0.15 + vec3(0.0, 0.6, 1.0))\n    return vec4(col, 1.0)\n",
  "particles.pyre": "# Particle step: gravity, drag and a bouncy floor.\nuniform dt: float\nuniform count: int\nbuffer px: [float]\nbuffer py: [float]\nbuffer vx: [float]\nbuffer vy: [float]\n\nconst GRAVITY = -9.81\nconst DRAG = 0.995\n\n@kernel(128)\nfn simulate(id: int):\n    if id >= count:\n        return\n    vy[id] += GRAVITY * dt\n    vx[id] *= DRAG\n    vy[id] *= DRAG\n    px[id] += vx[id] * dt\n    py[id] += vy[id] * dt\n    if py[id] < 0.0:\n        py[id] = -py[id]\n        vy[id] = -vy[id] * 0.8\n",
